def can_finish(numCourses, prerequisites):
    graph = [[] for _ in range(numCourses)]
    for a, b in prerequisites:
        graph[b].append(a)
    # 0=unvisited, 1=visiting, 2=visited
    state = [0] * numCourses
    def dfs(node):
        if state[node] == 1:
            return False  # cycle
        if state[node] == 2:
            return True
        state[node] = 1
        for nei in graph[node]:
            if not dfs(nei):
                return False
        state[node] = 2
        return True
    return all(dfs(i) for i in range(numCourses))

